<template>
  <div class="space-y-4 min-w-0"><p v-if="error" class="alert-error" role="alert">{{ error }}<button class="text-link ml-2" @click="load">重新读取</button></p>
    <section class="section-panel p-4"><div class="flex flex-wrap justify-between gap-3"><h2 class="font-semibold">多服务可靠发布</h2><button class="btn-primary" :disabled="busy || !groups.length" @click="edit">评审应用发布</button></div><p class="mt-3 text-sm leading-6 text-surface-400">固定完整 Compose 配置和全部运行镜像，依赖先行，每个更新服务均需通过容器状态和 HTTP 验收。中间失败会停止后续服务；只有预先授权才会按反向顺序回退已更新服务。</p><p class="mt-2 text-xs leading-6 text-surface-400">所有服务需运行且为单副本，待更新服务需已配置健康目标。不可逆或兼容性未知的数据迁移不能进入此流程。评审有效 15 分钟，目标镜像需事先准备在节点。配置快照包含展开的环境变量，以 0600 权限保存在项目目录。</p></section>
    <p v-if="loaded && !releases.length" class="text-sm text-surface-400">暂无多服务发布记录。</p>
    <section v-for="release in releases" :key="release.id" class="section-panel p-4"><div class="flex flex-wrap justify-between gap-2"><h3 class="font-semibold">{{ release.review.projectName }} · {{ release.hostId }}</h3><strong class="text-sm" :class="release.status === 'succeeded' ? 'text-status-ok' : 'text-status-warn'">{{ status(release.status) }}</strong></div><p class="mt-3 text-sm break-words">执行顺序：{{ release.review.order.join(' → ') }}</p><p class="mt-2 text-xs text-surface-400">{{ time(release.createdAt) }} · {{ release.approvedBy ? '批准人 ' + release.approvedBy : '尚未批准' }} · 回退{{ release.result.allowRollback ? '已预授权' : '未授权' }}</p><p v-if="release.error" class="mt-2 text-xs text-status-warn">{{ release.error }}</p>
      <details class="mt-3"><summary class="cursor-pointer text-sm">镜像、数据兼容声明与依赖依据</summary><div v-for="step in release.review.services" :key="step.serviceName" class="mt-3 border-l border-surface-700 pl-3"><p class="text-sm">{{ step.serviceName }} · {{ step.migration === 'none' ? '无数据迁移' : '数据双向兼容' }}</p><p class="mt-1 text-xs leading-6">{{ step.compatibilityNote }}</p><p class="mt-1 break-all font-mono text-xs text-surface-400">旧 {{ step.old.imageId }}<br />新 {{ step.next.imageId }}</p></div><p v-for="edge in release.review.graph.edges" :key="edge.service + edge.dependency" class="mt-2 text-xs">{{ edge.dependency }} → {{ edge.service }} · {{ edge.reason }}</p></details>
      <div v-if="release.result.steps?.length" class="mt-4 grid gap-3 sm:grid-cols-2"><div><h4 class="font-semibold text-sm">发布验收</h4><p v-for="step in release.result.steps" :key="step.serviceName" class="mt-2 text-xs">{{ step.serviceName }}：{{ step.passed && step.exitCode === 0 ? '通过' : '未通过' }} · {{ step.evidence.length }} 次观测</p></div><div><h4 class="font-semibold text-sm">回退验收</h4><p v-for="step in release.result.rollbackSteps || []" :key="step.serviceName" class="mt-2 text-xs">{{ step.serviceName }}：{{ step.passed && step.exitCode === 0 ? '通过' : '未通过' }}</p></div></div>
      <details v-if="release.result.steps?.length || release.status === 'outcome_unknown'" class="mt-3"><summary class="cursor-pointer text-xs">完整执行证据</summary><pre class="mt-2 max-h-80 overflow-auto whitespace-pre-wrap break-all text-xs">{{ JSON.stringify(release.result, null, 2) }}</pre></details>
      <div class="mt-4 flex flex-wrap gap-2"><button v-if="release.status === 'reviewed'" class="btn-primary btn-sm" :disabled="busy" @click="approval = { release, allowRollback: false, compatibilityConfirmed: false }; formError = ''">审阅并批准</button><button v-if="['reviewed', 'queued'].includes(release.status)" class="btn-secondary btn-sm" :disabled="busy" @click="cancel(release)">取消发布</button><button v-if="release.status === 'outcome_unknown'" class="btn-secondary btn-sm" :disabled="busy" @click="acknowledgement = { release, reason: '' }; formError = ''">核对全部服务后关闭</button></div>
    </section>
    <BaseModal :show="!!draft" title="评审多服务发布" :close-disabled="busy" size-class="max-w-3xl" @close="draft = null"><form v-if="draft" class="space-y-4" @submit.prevent="review"><p v-if="formError" class="alert-error" role="alert">{{ formError }}</p><fieldset :disabled="busy" class="space-y-4"><label class="form-grid-label"><span>应用与节点</span><select v-model="draft.group" class="input w-full" @change="choose"><option v-for="group in groups" :key="group.key" :value="group.key">{{ group.name }}</option></select></label><article v-for="step in draft.services" :key="step.profileId" class="section-panel p-3 space-y-3"><label class="flex gap-2 text-sm"><input v-model="step.selected" type="checkbox" />{{ step.serviceName }}</label><template v-if="step.selected"><label class="form-grid-label"><span>节点上已准备的新镜像</span><input v-model.trim="step.image" class="input w-full" required maxlength="300" /></label><label class="form-grid-label"><span>数据迁移兼容性</span><select v-model="step.migration" class="input w-full" required><option value="none">无数据迁移</option><option value="backward_compatible">新旧版本数据双向兼容</option><option value="unknown">未知或不可逆（会阻止发布）</option></select></label><label class="form-grid-label"><span>兼容依据与核验说明</span><textarea v-model="step.compatibilityNote" class="input w-full" rows="2" minlength="8" maxlength="1000" required /></label></template></article><button class="btn-primary" :disabled="busy || draft.services.filter(row => row.selected).length < 2">生成完整应用评审</button></fieldset></form></BaseModal>
    <BaseModal :show="!!approval" title="批准多服务发布" :close-disabled="busy" @close="approval = null"><form v-if="approval" class="space-y-4" @submit.prevent="approve"><p v-if="formError" class="alert-error" role="alert">{{ formError }}</p><p class="font-semibold">{{ approval.release.review.projectName }} · {{ approval.release.hostId }}</p><p class="text-sm">依次更新：{{ approval.release.review.order.join(' → ') }}</p><p class="text-sm leading-6">更新会重建服务容器并可能中断业务。每个服务连续三次通过验收且保持至少 30 秒稳定后才继续，最终还会联合复验。失联或结果未知时停止自动操作。</p><label class="flex items-start gap-2 text-sm"><input v-model="approval.compatibilityConfirmed" type="checkbox" required /><span>已核对各服务的数据迁移说明，确认新旧镜像与数据双向兼容。</span></label><label class="flex items-start gap-2 text-sm"><input v-model="approval.allowRollback" type="checkbox" /><span>授权失败时反序回退已更新服务。{{ approval.release.review.rollbackScope }}</span></label><button class="btn-primary" :disabled="busy || !approval.compatibilityConfirmed">批准当前评审并执行</button></form></BaseModal>
    <BaseModal :show="!!acknowledgement" title="核对未知发布结果" :close-disabled="busy" @close="acknowledgement = null"><form v-if="acknowledgement" class="space-y-4" @submit.prevent="acknowledge"><p v-if="formError" class="alert-error" role="alert">{{ formError }}</p><p class="text-sm leading-6">核对所有服务的实际镜像、数据和应用健康。系统将记录当前状态；关闭不代表原发布成功。</p><textarea v-model="acknowledgement.reason" class="input w-full" rows="4" minlength="8" maxlength="1000" required /><button class="btn-primary" :disabled="busy">记录核对结果并关闭</button></form></BaseModal>
  </div>
</template>
<script setup>
import { ref, computed, onMounted, onActivated, onDeactivated, onBeforeUnmount } from 'vue';
import { api } from '../api/client.js';
import BaseModal from './common/BaseModal.vue';
const props = defineProps({ profiles: { type: Array, default: () => [] } });
const releases = ref([]), error = ref(''), formError = ref(''), busy = ref(false), loaded = ref(false), draft = ref(null), approval = ref(null), acknowledgement = ref(null);
const groups = computed(() => {
  const values = new Map(); for (const profile of props.profiles.filter(row => row.enabled)) { const key = profile.hostId + ':' + profile.projectId; if (!values.has(key)) values.set(key, { key, name: profile.projectName + ' · ' + profile.hostId, profiles: [] }); values.get(key).profiles.push(profile); }
  return [...values.values()].filter(group => new Set(group.profiles.map(row => row.serviceName)).size >= 2);
});
const time = value => new Date(value).toLocaleString('zh-CN', { hour12: false });
const status = value => ({ reviewed: '待批准', queued: '排队中', checking: '检查中', executing: '更新中', verifying: '验收中', succeeded: '发布验收通过', failed: '发布未通过', blocked: '执行前已阻止', rolling_back: '回退中', verifying_rollback: '回退验收中', rolled_back: '已回退并验收', rollback_failed: '回退未通过', outcome_unknown: '结果未知，需核对', cancelled: '已取消', closed: '已核对关闭，未验证成功' })[value] || value;
let active = false, disposed = false, epoch = 0, loading = false, controller, timer;
async function load() {
  if (!active || loading || busy.value) return; const current = ++epoch; loading = true; controller = new AbortController();
  try { const data = await api.getSreResource('releases', controller.signal); if (active && current === epoch) { releases.value = data.releases; loaded.value = true; error.value = ''; } }
  catch (cause) { if (active && current === epoch) error.value = cause.message; }
  finally { if (current === epoch) loading = false; }
}
function edit() { draft.value = { group: groups.value[0]?.key, services: [] }; formError.value = ''; choose(); }
function choose() { const seen = new Set(); draft.value.services = (groups.value.find(row => row.key === draft.value.group)?.profiles || []).filter(row => { if (seen.has(row.serviceName)) return false; seen.add(row.serviceName); return true; }).map(row => ({ selected: false, profileId: row.id, serviceName: row.serviceName, image: '', migration: 'none', compatibilityNote: '' })); }
async function act(work, complete) {
  if (!active || busy.value) return; controller?.abort(); epoch++; loading = false; const current = epoch; busy.value = true; error.value = ''; formError.value = '';
  try { await work(); if (active && current === epoch) complete?.(); }
  catch (cause) { if (active && current === epoch) { if (draft.value || approval.value || acknowledgement.value) formError.value = cause.message; else error.value = cause.message; } }
  finally { busy.value = false; if (active && current === epoch) void load(); }
}
function review() { const services = draft.value.services.filter(row => row.selected).map(({ profileId, image, migration, compatibilityNote }) => ({ profileId, image, migration, compatibilityNote })); if (services.some(row => row.migration === 'unknown')) { formError.value = '不可逆或未知数据迁移不能进入可靠发布流程'; return; } return act(() => api.sreOperation('releases/review', { services }), () => { draft.value = null; }); }
function approve() { const value = approval.value; return act(() => api.sreOperation('releases/' + value.release.id + '/approve', { confirm: 'APPLY_APPLICATION_RELEASE', fingerprint: value.release.fingerprint, allowRollback: value.allowRollback, compatibilityConfirmed: value.compatibilityConfirmed }), () => { approval.value = null; }); }
function cancel(release) { return act(() => api.sreOperation('changes/' + release.id + '/cancel', {})); }
function acknowledge() { const value = acknowledgement.value; return act(() => api.sreOperation('changes/' + value.release.id + '/acknowledge', { reason: value.reason }), () => { acknowledgement.value = null; }); }
function start() { if (active || disposed) return; active = true; void load(); timer = setInterval(load, 5000); }
function stop() { active = false; controller?.abort(); epoch++; loading = false; clearInterval(timer); }
onMounted(start); onActivated(start); onDeactivated(stop); onBeforeUnmount(() => { disposed = true; stop(); });
</script>
